document.querySelectorAll('form[data-sb-form-api-token]').forEach(function(form){form.addEventListener('submit',function(event){event.preventDefault();var note=form.querySelector('[data-local-form-note]');if(!note){note=document.createElement('p');note.dataset.localFormNote='true';note.setAttribute('role','status');form.append(note);}note.textContent='This form is not connected yet. Connect a backend before accepting submissions.';});var button=form.querySelector('[type=submit]');if(button){button.classList.remove('disabled');button.removeAttribute('disabled');}});
